"""Original, synthetic repository-repair fixtures, not SWE-bench instances.

Visible tests are supplied to the agent; hidden tests are never sent to it.
Each task has an API consumer as well as the implementation file, and tests
run in a separate no-network container. Inputs are deliberately public/synthetic.
"""


def case(name, issue, implementation, api, visible, hidden):
    return dict(name=name, issue=issue, files={"impl.py": implementation, "api.py": api,
                "test_visible.py": "import unittest\nfrom api import *\n" + visible},
                editable=["impl.py", "api.py"],
                hidden="import unittest\nfrom api import *\n" + hidden)


TASKS = [
    case("ttl-cache", "Fix cache expiry at the exact deadline and caching of falsy values. Reject negative TTL with ValueError without modifying the cache. TTL zero expires immediately. Preserve the public API and injected clock; do not mutate tests.",
         "class Cache:\n    def __init__(self, clock):\n        self.clock = clock\n        self.items = {}\n    def put(self, key, value, ttl):\n        self.items[key] = (value, self.clock() + ttl)\n    def get(self, key, default=None):\n        if key not in self.items: return default\n        value, deadline = self.items[key]\n        if self.clock() > deadline:\n            del self.items[key]\n            return default\n        return value\n",
         "from impl import Cache\ndef lookup(cache, key, loader, ttl):\n    value = cache.get(key)\n    if not value:\n        value = loader()\n        cache.put(key, value, ttl)\n    return value\n",
         "class Visible(unittest.TestCase):\n    def test_hit(self):\n        c = Cache(lambda: 0); c.put('a', 3, 10)\n        self.assertEqual(lookup(c, 'a', lambda: 99, 10), 3)\n    def test_deadline(self):\n        now = [0]; c = Cache(lambda: now[0]); c.put('a', 3, 1); now[0] = 1\n        self.assertEqual(c.get('a', 'miss'), 'miss')\n",
         "class Hidden(unittest.TestCase):\n    def test_falsy(self):\n        for value in (0, False, '', [], None):\n            c = Cache(lambda: 0); c.put('k', value, 1)\n            self.assertIs(lookup(c, 'k', lambda: self.fail('loader on cache hit'), 1), value)\n    def test_negative(self):\n        c = Cache(lambda: 4); c.put('x', 9, 3)\n        with self.assertRaises(ValueError): c.put('x', 2, -1)\n        self.assertEqual(c.get('x'), 9)\n    def test_zero(self):\n        c = Cache(lambda: 0); c.put('z', 1, 0); self.assertIsNone(c.get('z'))\n"),
    case("deep-config", "Fix recursive configuration overlay. Nested dictionaries must merge recursively; lists/scalars replace existing values. Return independent deep copies, never mutate or alias either input, including unchanged branches. Preserve API.",
         "def merge(base, overlay):\n    result = base.copy()\n    for key, value in overlay.items():\n        result[key] = value\n    return result\n",
         "from impl import merge\ndef configure(defaults, user):\n    return merge(defaults, user)\n",
         "class Visible(unittest.TestCase):\n    def test_nested(self):\n        self.assertEqual(configure({'a': {'x': 1, 'y': 2}}, {'a': {'x': 3}}), {'a': {'x': 3, 'y': 2}})\n    def test_replace(self):\n        self.assertEqual(configure({'a': [1]}, {'a': [2]}), {'a': [2]})\n",
         "class Hidden(unittest.TestCase):\n    def test_no_alias(self):\n        b = {'a': {'l': [1]}, 'z': [5]}; o = {'a': {'k': [2]}}; r = configure(b, o)\n        r['a']['l'].append(9); r['a']['k'].append(8); r['z'].append(7)\n        self.assertEqual(b, {'a': {'l': [1]}, 'z': [5]}); self.assertEqual(o, {'a': {'k': [2]}})\n    def test_type_switch(self):\n        self.assertEqual(configure({'a': {'x': 1}}, {'a': None}), {'a': None})\n        self.assertEqual(configure({'a': 2}, {'a': {'b': 3}}), {'a': {'b': 3}})\n"),
    case("stable-dag", "Fix deployment ordering. The input maps each node to its dependencies. Return dependencies before dependents, always choosing the lexicographically smallest currently-ready node. Include dependencies that are not keys. Raise ValueError on every cycle, including self-cycles. Do not mutate the input.",
         "def order(graph):\n    return sorted(graph)\n",
         "from impl import order\ndef deployment_order(graph):\n    return order(graph)\n",
         "class Visible(unittest.TestCase):\n    def test_dependency(self):\n        self.assertEqual(deployment_order({'a': ['z'], 'z': []}), ['z', 'a'])\n    def test_cycle(self):\n        with self.assertRaises(ValueError): deployment_order({'a': ['b'], 'b': ['a']})\n",
         "class Hidden(unittest.TestCase):\n    def test_missing(self):\n        self.assertEqual(deployment_order({'a': ['z']}), ['z', 'a'])\n    def test_ready_priority(self):\n        g = {'b': ['a'], 'c': [], 'a': []}\n        self.assertEqual(deployment_order(g), ['a', 'b', 'c']); self.assertEqual(g, {'b': ['a'], 'c': [], 'a': []})\n    def test_self(self):\n        with self.assertRaises(ValueError): deployment_order({'a': ['a']})\n    def test_duplicates(self):\n        self.assertEqual(deployment_order({'a': ['z', 'z']}), ['z', 'a'])\n"),
    case("retry-boundary", "Fix bounded retries. max_attempts counts total calls, must be positive. Retry only the specified exception classes. Sleep base_delay * 2**retry_index after a retryable failure only when another attempt remains. On exhaustion raise the original final exception. Negative base_delay must raise ValueError before calling operation. Preserve injected sleeper and API.",
         "def retry(operation, max_attempts, base_delay, exceptions, sleeper):\n    for i in range(max_attempts + 1):\n        try: return operation()\n        except exceptions:\n            sleeper(base_delay * 2**i)\n    return None\n",
         "from impl import retry\ndef run(operation, max_attempts=3, base_delay=1, exceptions=(OSError,), sleeper=lambda _: None):\n    return retry(operation, max_attempts, base_delay, exceptions, sleeper)\n",
         "class Visible(unittest.TestCase):\n    def test_success(self):\n        self.assertEqual(run(lambda: 7), 7)\n    def test_exhausted(self):\n        count = []; sleeps = []\n        def op(): count.append(1); raise OSError('failed')\n        with self.assertRaises(OSError): run(op, max_attempts=2, sleeper=sleeps.append)\n        self.assertEqual(len(count), 2); self.assertEqual(sleeps, [1])\n",
         "class Hidden(unittest.TestCase):\n    def test_validation(self):\n        for kw in ({'max_attempts': 0}, {'max_attempts': -2}, {'base_delay': -1}):\n            with self.assertRaises(ValueError): run(lambda: self.fail('called invalid op'), **kw)\n    def test_backoff_and_identity(self):\n        sleeps = []; exc = OSError('original')\n        def op(): raise exc\n        with self.assertRaises(OSError) as cm: run(op, max_attempts=4, base_delay=.5, sleeper=sleeps.append)\n        self.assertIs(cm.exception, exc); self.assertEqual(sleeps, [.5, 1, 2])\n    def test_other_exception(self):\n        def op(): raise RuntimeError('not retryable')\n        with self.assertRaises(RuntimeError): run(op, sleeper=lambda _: self.fail('slept'))\n"),
    case("atomic-ledger", "Fix atomic money transfers. Ledger balances are Decimal amounts; string amounts must convert exactly via Decimal. Reject negative amounts, unknown accounts and insufficient funds with ValueError, leaving every balance unchanged. Self-transfers are a no-op after validation; amount zero is valid. transfer returns None. Preserve the balance dictionary and public API.",
         "from decimal import Decimal\nclass Ledger:\n    def __init__(self, balances):\n        self.balances = {k: Decimal(str(v)) for k, v in balances.items()}\n    def transfer(self, source, dest, amount):\n        amount = Decimal(str(float(amount)))\n        self.balances[source] -= amount\n        self.balances[dest] += amount\n        if self.balances[source] < 0: raise ValueError('insufficient')\n",
         "from impl import Ledger\nfrom decimal import Decimal\ndef transfer(ledger, source, dest, amount):\n    return ledger.transfer(source, dest, amount)\n",
         "class Visible(unittest.TestCase):\n    def test_transfer(self):\n        l = Ledger({'a': '1', 'b': '0'}); transfer(l, 'a', 'b', '.25')\n        self.assertEqual(l.balances, {'a': Decimal('.75'), 'b': Decimal('.25')})\n    def test_atomic(self):\n        l = Ledger({'a': '1', 'b': '0'})\n        with self.assertRaises(ValueError): transfer(l, 'a', 'b', '2')\n        self.assertEqual(l.balances, {'a': Decimal('1'), 'b': Decimal('0')})\n",
         "class Hidden(unittest.TestCase):\n    def test_exact(self):\n        l = Ledger({'a': '1', 'b': '0'}); transfer(l, 'a', 'b', '.123456789123456789')\n        self.assertEqual(l.balances['b'], Decimal('.123456789123456789'))\n    def test_bad(self):\n        for source, dest, amount in [('a', 'b', '-1'), ('missing', 'b', '0'), ('a', 'missing', '.5')]:\n            l = Ledger({'a': '1', 'b': '0'}); before = l.balances.copy()\n            with self.assertRaises(ValueError): transfer(l, source, dest, amount)\n            self.assertEqual(l.balances, before)\n    def test_self(self):\n        l = Ledger({'a': '1'}); self.assertIsNone(transfer(l, 'a', 'a', '.5')); self.assertEqual(l.balances['a'], Decimal('1'))\n"),
    case("window-split", "Fix rolling windows. For positive integer size and step, windows yields independent full-size lists, beginning at offsets 0, step, 2*step, etc. Stop before an incomplete window. Accept any iterable, including one-shot generators; consume it lazily. Validate size and step > 0 with ValueError. Preserve API.",
         "def windows(values, size, step=1):\n    values = list(values)\n    for i in range(0, len(values), step):\n        yield values[i:i + size]\n",
         "from impl import windows\ndef chunks(values, size, step=1):\n    return windows(values, size, step)\n",
         "class Visible(unittest.TestCase):\n    def test_full_only(self):\n        self.assertEqual(list(chunks(range(5), 3)), [[0, 1, 2], [1, 2, 3], [2, 3, 4]])\n    def test_stride(self):\n        self.assertEqual(list(chunks(range(8), 2, 3)), [[0, 1], [3, 4], [6, 7]])\n",
         "class Hidden(unittest.TestCase):\n    def test_lazy(self):\n        consumed = []\n        def source():\n            for i in range(1000): consumed.append(i); yield i\n        w = chunks(source(), 3); self.assertEqual(next(w), [0, 1, 2]); self.assertLessEqual(len(consumed), 4)\n    def test_independent(self):\n        w = chunks(iter(range(6)), 2); a = next(w); a[0] = 99; self.assertEqual(next(w), [1, 2])\n    def test_invalid(self):\n        for size, step in [(0, 1), (-1, 1), (2, 0), (2, -1)]:\n            with self.assertRaises(ValueError): list(chunks(range(5), size, step))\n    def test_empty(self):\n        self.assertEqual(list(chunks([], 1)), []); self.assertEqual(list(chunks([1], 2)), [])\n"),
]
